{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/held-out-sonnet-all/cell-5DkrwK/src/cache.js","content":"/**
 * Least-recently-used cache with per-entry lifetimes, a byte budget measured
 * by a caller-supplied sizer, and an injectable clock.
 *
 * Recency order is tracked with a doubly linked list (using sentinel head and
 * tail nodes) alongside a `Map` from key to node, so `get`, `set`, `has`,
 * `peek`, and `delete` each do a constant amount of work regardless of how
 * many entries are stored.
 */

/**
 * Validates that a value is a string key.
 * @param {unknown} key Candidate key.
 * @returns {void}
 */
function checkKey(key) {
  if (typeof key !== 'string') {
    throw new TypeError('key must be a string');
  }
}

/**
 * Validates that a value is a non-negative number, `Infinity` included.
 * @param {unknown} ttlMs Candidate lifetime.
 * @returns {number} The validated lifetime.
 */
function checkTtl(ttlMs) {
  if (typeof ttlMs !== 'number' || Number.isNaN(ttlMs) || ttlMs < 0) {
    throw new TypeError('ttlMs must be a non-negative number');
  }
  return ttlMs;
}

/**
 * Validates that a value is a non-negative safe integer byte count.
 * @param {unknown} bytes Candidate byte count.
 * @returns {number} The validated byte count.
 */
function checkSizeResult(bytes) {
  if (!Number.isSafeInteger(bytes) || bytes < 0) {
    throw new TypeError('sizeOf must return a non-negative safe integer');
  }
  return bytes;
}

export class LruTtlCache {
  /** @type {Map<string, object>} */
  #map = new Map();
  #maxBytes;
  #ttlMs;
  #clock;
  #sizeOf;
  #onEvict;
  #bytes = 0;
  #hits = 0;
  #misses = 0;
  #evictions = 0;
  #expirations = 0;
  /** @type {{key: null, prev: null, next: object}} */
  #head;
  /** @type {{key: null, prev: object, next: null}} */
  #tail;

  /**
   * @param {object} options Cache options.
   * @param {number} options.maxBytes Byte budget; a positive safe integer.
   * @param {number} [options.ttlMs] Default lifetime, `Infinity` by default.
   * @param {() => number} [options.clock] Millisecond clock, `Date.now` by default.
   * @param {(value: unknown, key: string) => number} [options.sizeOf] Sizer, one byte per entry by default.
   * @param {(key: string, value: unknown, reason: string) => void} [options.onEvict] Removal callback.
   */
  constructor(options) {
    if (typeof options !== 'object' || options === null) {
      throw new TypeError('options must be an object');
    }
    const {
      maxBytes,
      ttlMs = Number.POSITIVE_INFINITY,
      clock = Date.now,
      sizeOf = () => 1,
      onEvict = () => {},
    } = options;

    if (!Number.isSafeInteger(maxBytes) || maxBytes <= 0) {
      throw new TypeError('maxBytes must be a positive integer');
    }
    this.#maxBytes = maxBytes;

    this.#ttlMs = checkTtl(ttlMs);

    if (typeof clock !== 'function') {
      throw new TypeError('clock must be a function');
    }
    this.#clock = clock;

    if (typeof sizeOf !== 'function') {
      throw new TypeError('sizeOf must be a function');
    }
    this.#sizeOf = sizeOf;

    if (typeof onEvict !== 'function') {
      throw new TypeError('onEvict must be a function');
    }
    this.#onEvict = onEvict;

    this.#head = { key: null, value: null, prev: null, next: null };
    this.#tail = { key: null, value: null, prev: null, next: null };
    this.#head.next = this.#tail;
    this.#tail.prev = this.#head;
  }

  /** @returns {number} Byte budget the cache was built with. */
  get capacity() {
    return this.#maxBytes;
  }

  /** @returns {number} Number of stored entries, expired ones included. */
  get size() {
    return this.#map.size;
  }

  /** @returns {number} Bytes charged by the stored entries. */
  get bytes() {
    return this.#bytes;
  }

  /**
   * Unlinks a node from the recency list.
   * @param {object} node Node to unlink.
   * @returns {void}
   */
  #unlink(node) {
    node.prev.next = node.next;
    node.next.prev = node.prev;
  }

  /**
   * Appends a node to the most-recently-used end of the recency list.
   * @param {object} node Node to append.
   * @returns {void}
   */
  #appendMru(node) {
    const last = this.#tail.prev;
    last.next = node;
    node.prev = last;
    node.next = this.#tail;
    this.#tail.prev = node;
  }

  /**
   * Moves a node to the most-recently-used end of the recency list.
   * @param {object} node Node to move.
   * @returns {void}
   */
  #touch(node) {
    this.#unlink(node);
    this.#appendMru(node);
  }

  /**
   * Reports whether a node's lifetime has fully elapsed.
   * @param {object} node Node to check.
   * @returns {boolean} True when the node is expired.
   */
  #isExpired(node) {
    return this.#clock() - node.storedAt >= node.ttlMs;
  }

  /**
   * Removes a node from the map and the recency list, adjusts byte
   * accounting and counters, and reports it.
   * @param {object} node Node to remove.
   * @param {'expire' | 'size' | 'replace'} reason Removal reason.
   * @returns {void}
   */
  #removeEntry(node, reason) {
    this.#map.delete(node.key);
    this.#unlink(node);
    this.#bytes -= node.bytes;
    if (reason === 'size') {
      this.#evictions += 1;
    } else if (reason === 'expire') {
      this.#expirations += 1;
    }
    this.#onEvict(node.key, node.value, reason);
  }

  /**
   * Stores a value, replacing any entry already under the key.
   * @param {string} key Cache key.
   * @param {unknown} value Value to store.
   * @param {{ttlMs?: number}} [options] Per-entry lifetime override.
   * @returns {boolean} False when the value alone exceeds the byte budget.
   */
  set(key, value, options = {}) {
    checkKey(key);
    if (typeof options !== 'object' || options === null) {
      throw new TypeError('options must be an object');
    }
    const ttlMs = options.ttlMs === undefined ? this.#ttlMs : checkTtl(options.ttlMs);
    const entryBytes = checkSizeResult(this.#sizeOf(value, key));

    const existing = this.#map.get(key);
    if (existing !== undefined) {
      this.#removeEntry(existing, 'replace');
    }

    if (entryBytes > this.#maxBytes) {
      return false;
    }

    const node = {
      key,
      value,
      bytes: entryBytes,
      storedAt: this.#clock(),
      ttlMs,
      prev: null,
      next: null,
    };
    this.#map.set(key, node);
    this.#appendMru(node);
    this.#bytes += entryBytes;

    while (this.#bytes > this.#maxBytes) {
      const victim = this.#head.next;
      const reason = this.#isExpired(victim) ? 'expire' : 'size';
      this.#removeEntry(victim, reason);
    }

    return true;
  }

  /**
   * Reads a value and marks the entry most-recently used.
   * @param {string} key Cache key.
   * @returns {unknown} Stored value, or undefined when absent or expired.
   */
  get(key) {
    checkKey(key);
    const node = this.#map.get(key);
    if (node === undefined) {
      this.#misses += 1;
      return undefined;
    }
    if (this.#isExpired(node)) {
      this.#removeEntry(node, 'expire');
      this.#misses += 1;
      return undefined;
    }
    this.#touch(node);
    this.#hits += 1;
    return node.value;
  }

  /**
   * Reads a value without changing recency or hit counters.
   * @param {string} key Cache key.
   * @returns {unknown} Stored value, or undefined when absent or expired.
   */
  peek(key) {
    checkKey(key);
    const node = this.#map.get(key);
    if (node === undefined) {
      return undefined;
    }
    if (this.#isExpired(node)) {
      this.#removeEntry(node, 'expire');
      return undefined;
    }
    return node.value;
  }

  /**
   * Reports whether a live entry is stored, without changing recency or hit
   * counters.
   * @param {string} key Cache key.
   * @returns {boolean} True when a live entry exists.
   */
  has(key) {
    checkKey(key);
    const node = this.#map.get(key);
    if (node === undefined) {
      return false;
    }
    if (this.#isExpired(node)) {
      this.#removeEntry(node, 'expire');
      return false;
    }
    return true;
  }

